INSERT INTO `livro` VALUES (1,'Pollyanna','Eleanor H. Porter','Romance infantojuvenil','\"Pollyanna\", de Eleanor H. Porter, é um romance publicado em 1913. Quando Pollyanna, uma órfã de onze anos, chega para morar com sua severa tia Polly em uma pequena cidade de Vermont, ela traz consigo \"O Jogo da Alegria\" — encontrar algo positivo em cada situação, por mais difícil que seja. Seu otimismo contagiante começa a transformar a vida dos habitantes mais problemáticos da cidade. Mas quando a tragédia acontece, até mesmo a alegria inabalável de Pollyanna enfrenta seu maior teste.',1913,'https://gutenberg.org/cache/epub/1450/images/cover.jpg','https://gutenberg.org/cache/epub/1450/pg1450-images.html'),(2,'Jane Eyre: Uma Autobiografia','Charlotte Brontë','Romance','\"Jane Eyre: Uma Autobiografia\", de Charlotte Brontë, é um romance publicado em 1847. A obra narra a vida de Jane Eyre, desde sua infância opressiva até sua educação e a vida adulta, quando se torna governanta em Thornfield Hall e se apaixona pelo misterioso Sr. Rochester. Contada em primeira pessoa, esta obra inovadora de formação explora o desenvolvimento moral e espiritual, abordando temas como classe social, religião, sexualidade e feminismo. A história se desenrola em cinco fases distintas, cada uma moldando a jornada de Jane rumo à independência e ao sentimento de pertencimento.',1847,'https://www.gutenberg.org/cache/epub/1260/pg1260.cover.medium.jpg','https://gutenberg.org/cache/epub/1260/pg1260-images.html'),(3,'O Jardim Secreto','Frances Hodgson Burnett','Romance','\"O Jardim Secreto\", de Frances Hodgson Burnett, é um romance infantil publicado pela primeira vez em 1911. Quando a órfã Mary Lennox chega à sombria mansão de seu tio em Yorkshire, ela descobre um jardim trancado, abandonado há dez anos. Ao explorar esse mundo oculto, Mary desvenda segredos de família e encontra um companheiro inesperado: seu primo Colin, que está acamado. Juntamente com um menino amante da natureza chamado Dickon, as crianças trazem o jardim esquecido de volta à vida, transformando-se no processo.',1911,'https://www.gutenberg.org/cache/epub/113/pg113.cover.medium.jpg','https://gutenberg.org/cache/epub/113/pg113-images.html'),(4,'Drácula','Bram Stoker','Romance Gótico','\"Drácula\", de Bram Stoker, é um romance gótico de terror publicado em 1897. Narrada por meio de cartas, entradas de diário e artigos de jornal, a história acompanha o encontro aterrador do advogado Jonathan Harker com o Conde Drácula na Transilvânia. Quando o vampiro viaja para a Inglaterra e começa a atacar vítimas em Whitby, um pequeno grupo liderado pelo Professor Abraham Van Helsing precisa caçá-lo. Esta obra seminal da ficção gótica tornou-se a peça central da literatura vampírica, moldando profundamente a concepção popular de vampiros por gerações. ',1897,'https://www.gutenberg.org/cache/epub/345/pg345.cover.medium.jpg','https://gutenberg.org/cache/epub/345/pg345-images.html'),(5,'Anne de Green Gables','L. M. Montgomery','Romance','\"Anne de Green Gables\", de L. M. Montgomery, é um romance publicado em 1908. Quando a órfã Anne Shirley, de onze anos, chega por engano à fazenda Green Gables, os irmãos Cuthbert haviam solicitado um menino para ajudar nos trabalhos agrícolas. Imaginativa, falante e ansiosa por pertencer àquele lugar, Anne precisa provar que merece ficar. A história acompanha suas aventuras na vila de Avonlea — fazendo amigos, se destacando na escola, entrando em conflito com o rival Gilbert Blythe e transformando a vida de todos ao seu redor. ',1908,'https://www.gutenberg.org/cache/epub/45/pg45.cover.medium.jpg','https://gutenberg.org/cache/epub/45/pg45-images.html'),(6,'Alice no País das Maravilhas','Lewis Carroll','Fantasia','\"Alice no País das Maravilhas\", de Lewis Carroll, é um romance infantil publicado em 1865. Quando uma menina curiosa chamada Alice avista um Coelho Branco com um relógio de bolso, ela cai em uma toca de coelho e entra em um extraordinário mundo de fantasia repleto de criaturas antropomórficas peculiares. Esta obra pioneira de nonsense literário brinca com a lógica e a linguagem, criando um conto fantasioso que encanta tanto crianças quanto adultos. Ilustrada por John Tenniel, a obra ajudou a transformar a literatura infantil, de um instrumento didático para puro entretenimento.',1865,'https://www.gutenberg.org/cache/epub/11/pg11.cover.medium.jpg','https://gutenberg.org/cache/epub/11/pg11-images.html'),(7,'A Ilha do Tesouro','Robert Louis Stevenson','Aventura','\"A Ilha do Tesouro\", de Robert Louis Stevenson, é um romance de aventura publicado em 1883. Quando o jovem Jim Hawkins descobre um misterioso mapa do tesouro no baú de um pirata morto, ele parte com uma tripulação para encontrar o lendário ouro enterrado do Capitão Flint. Mas a bordo do navio Hispaniola, o perigo espreita: o charmoso cozinheiro de uma perna só, Long John Silver, lidera um bando de piratas amotinados com seus próprios planos mortais. Em uma ilha remota repleta de traições e violência, Jim precisa navegar por alianças instáveis e ameaças mortais para sobreviver a essa perigosa busca por fortuna. ',1883,'https://www.gutenberg.org/cache/epub/120/pg120.cover.medium.jpg','https://gutenberg.org/cache/epub/120/pg120-images.html'),(8,'Orgulho e Preconceito','Jane Austen','Romance','\"Orgulho e Preconceito\", de Jane Austen, é um romance publicado em 1813. A história acompanha Elizabeth Bennet, que precisa aprender a enxergar além das primeiras impressões e julgamentos precipitados. Com cinco filhas e uma propriedade que só pode ser herdada por homens, a família Bennet enfrenta a pressão financeira de fazer bons casamentos. Quando o rico Sr. Darcy chega à região rural onde vivem, seu orgulho e o preconceito de Elizabeth criam o cenário para mal-entendidos, verdades ocultas e revelações inesperadas sobre caráter e amor.',1813,'https://www.gutenberg.org/cache/epub/1342/pg1342.cover.medium.jpg','https://gutenberg.org/cache/epub/1342/pg1342-images.html'),(9,'A Máquina do Tempo','H. G. Wells','Ficção Científica','\"A Máquina do Tempo\", de H. G. Wells, é uma novela de ficção científica publicada em 1895. Um cientista da era vitoriana, conhecido como o Viajante do Tempo, viaja para o ano 802.701, onde descobre que a humanidade evoluiu para duas espécies distintas: os Eloi, semelhantes a crianças, e os Morlocks, selvagens. Esta obra inovadora popularizou o conceito de viagem no tempo e cunhou o termo \"máquina do tempo\". Wells cria uma visão assombrosa do futuro que explora as divisões de classe e a desigualdade social, levando os leitores a uma aventura inesquecível pelas possibilidades mais sombrias do tempo.',1895,'https://www.gutenberg.org/cache/epub/35/pg35.cover.medium.jpg','https://gutenberg.org/cache/epub/35/pg35-images.html'),(10,'Mulherzinhas','Louisa May Alcott','Romance','\"Mulherzinhas; ou, Meg, Jo, Beth e Amy\", de Louisa May Alcott, é um romance de formação publicado entre 1868 e 1869. A história acompanha quatro irmãs — Meg, Jo, Beth e Amy March — enquanto trilham o caminho da infância para a vida adulta em Massachusetts, durante a Guerra Civil Americana. Baseado livremente na própria família de Alcott, o romance explora temas como a vida doméstica, o trabalho e o amor, ao mesmo tempo que retrata as alegrias e os desafios da vida das mulheres do século XIX. Através de suas aventuras e dificuldades, as irmãs March personificam diferentes aspectos da juventude feminina americana.',1868,'[https://www.gutenberg.org/cache/epub/37106/pg37106.cover.medium.jpg](https://www.gutenberg.org/cache/epub/37106/pg37106.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/37106/pg37106-images.html](https://www.gutenberg.org/cache/epub/37106/pg37106-images.html)'),(11,'Os Miseráveis','Victor Hugo','Romance','\"Os Miseráveis\", de Victor Hugo, é um romance épico histórico francês publicado em 1862. Iniciando-se em 1815 e culminando na Revolta de Junho de 1832 em Paris, a obra acompanha a luta do ex-presidiário Jean Valjean pela redenção. O romance explora a natureza da lei e da graça, examinando temas como justiça, pobreza e amor através das vidas de personagens interligados na França do século XIX. Considerado um dos maiores romances do século, retrata os membros mais oprimidos da sociedade e sua luta por dignidade.',1862,'[https://www.gutenberg.org/cache/epub/135/pg135.cover.medium.jpg](https://www.gutenberg.org/cache/epub/135/pg135.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/135/pg135-images.html](https://www.gutenberg.org/cache/epub/135/pg135-images.html)'),(12,'O Morro dos Ventos Uivantes','Emily Brontë','Romance','\"O Morro dos Ventos Uivantes\", de Emily Brontë, é um romance publicado em 1847. Ambientado nos pântanos de Yorkshire, acompanha duas famílias proprietárias de terras e seus relacionamentos turbulentos com Heathcliff, um misterioso filho adotivo. Impulsionada por um amor obsessivo, possessão e vingança que atravessa gerações, a história se desenrola em meio a uma paixão sombria e crueldade. Este conto gótico desafiou a moralidade vitoriana com suas representações de abuso e conflito de classes, tornando-se, em última análise, um pilar da literatura inglesa, apesar da recepção inicialmente polarizada.',1847,'[https://www.gutenberg.org/cache/epub/768/pg768.cover.medium.jpg](https://www.gutenberg.org/cache/epub/768/pg768.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/768/pg768-images.html](https://www.gutenberg.org/cache/epub/768/pg768-images.html)'),(13,'Persuasão','Jane Austen','Romance','\"Persuasão\", de Jane Austen, é um romance publicado em 1817. Oito anos após ser persuadida a romper seu noivado com o oficial naval Frederick Wentworth, Anne Elliot, de vinte e sete anos, reencontra-o quando sua irmã aluga a propriedade da família. Agora rico e solteiro, Wentworth se mistura ao círculo social de Anne, enquanto ela observa em silêncio, sem perder seus sentimentos. À medida que mal-entendidos se desenrolam e novos laços se formam, a história explora se segundas chances no amor são possíveis quando o orgulho e os arrependimentos do passado se interpõem entre dois corações.',1817,'[https://www.gutenberg.org/cache/epub/105/pg105.cover.medium.jpg](https://www.gutenberg.org/cache/epub/105/pg105.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/105/pg105-images.html](https://www.gutenberg.org/cache/epub/105/pg105-images.html)'),(14,'Dom Casmurro','Machado de Assis','Romance','\"Dom Casmurro\", de Machado de Assis, é um romance publicado em 1899. Bento Santiago, um advogado rico na casa dos cinquenta, tenta reconectar os dois extremos de sua vida, relembrando suas memórias de infância, seu tempo no seminário e seu casamento com Capitu. No cerne de sua narrativa reside seu ciúme mórbido e suspeitas de adultério. Mas será que os leitores podem confiar na versão dos fatos apresentada por esse narrador pouco confiável? A questão da culpa de Capitu é deliberadamente ambígua, convidando a múltiplas interpretações.',1899,'[https://www.gutenberg.org/cache/epub/55752/pg55752.cover.medium.jpg](https://www.gutenberg.org/cache/epub/55752/pg55752.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/55752/pg55752-images.html](https://www.gutenberg.org/cache/epub/55752/pg55752-images.html)'),(15,'O Cortiço','Aluísio Azevedo','Romance','\"O Cortiço\", de Aluísio Azevedo, é um romance naturalista publicado em 1890. Ambientado em um cortiço do Rio de Janeiro no final do século XIX, a obra expõe a exploração e as duras condições de vida sob o capitalismo desenfreado. A história acompanha a ascensão implacável do comerciante português João Romão na escala social, enquanto narra as lutas dos diversos moradores do cortiço. Seus destinos entrelaçados revelam como o ambiente e o instinto moldam o comportamento humano, à medida que os personagens abandonam famílias, perseguem paixões proibidas e lutam pela sobrevivência em um mundo governado pelos mais fortes.',1890,'[https://www.gutenberg.org/cache/epub/69187/pg69187.cover.medium.jpg](https://www.gutenberg.org/cache/epub/69187/pg69187.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/69187/pg69187-images.html](https://www.gutenberg.org/cache/epub/69187/pg69187-images.html)'),(16,'O Guarani: romance brasileiro, Vol. 1 (de 2)','José Martiniano de Alencar','Romance','\"O Guarani: romance brasileiro, Vol. 1 (de 2)\", de José Martiniano de Alencar, é um romance publicado em 1857. Ambientado no Brasil colonial de 1604, acompanha Peri, um índio goitacá que se dedica a proteger Cecília, filha do nobre português Dom Antônio de Mariz. Quando o perigoso aventureiro Loredano chega à remota casa da família, que lembra um castelo, ele começa a planejar o sequestro de Cecília e a tomada do poder. Texto fundamental do Romantismo brasileiro, o romance mescla aventura, elementos góticos e temas de liberdade e identidade indígena.',1857,'[https://www.gutenberg.org/cache/epub/67724/pg67724.cover.medium.jpg](https://www.gutenberg.org/cache/epub/67724/pg67724.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/67724/pg67724-images.html](https://www.gutenberg.org/cache/epub/67724/pg67724-images.html)'),(17,'O Guarani: romance brasileiro, Vol. 2 (de 2)','José Martiniano de Alencar','Romance','\"O Guarani: romance brasileiro, Vol. 2 (de 2)\", de José Martiniano de Alencar, é um romance brasileiro publicado pela primeira vez em 1857. Ambientado no Brasil colonial de 1604, acompanha Peri, um nobre guerreiro indígena Goitacá que serve a uma família portuguesa que vive em um remoto povoado fortificado. Quando o aventureiro Loredano se infiltra na casa e planeja sequestrar Cecília, filha do senhor, a quem Peri protege com devoção, as tensões aumentam. Esta obra fundamental do Romantismo mescla aventura, violência e erotismo, explorando temas como liberdade, identidade indígena e independência brasileira.',1857,'[https://www.gutenberg.org/cache/epub/67725/pg67725.cover.medium.jpg](https://www.gutenberg.org/cache/epub/67725/pg67725.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/67725/pg67725-images.html](https://www.gutenberg.org/cache/epub/67725/pg67725-images.html)'),(18,'O Grande Gatsby','F. Scott Fitzgerald','Romance','\"O Grande Gatsby\", de F. Scott Fitzgerald, é um romance publicado em 1925. Ambientado na Era do Jazz em Long Island, acompanha o narrador Nick Carraway enquanto ele se vê envolvido no mundo de seu misterioso vizinho, Jay Gatsby, um milionário rico que dá festas extravagantes. Gatsby nutre uma obsessão por reencontrar Daisy Buchanan, uma mulher de seu passado agora casada com o abastado Tom. A história captura o glamour, o excesso e as complexidades morais da América dos anos 1920.',1925,'[https://www.gutenberg.org/cache/epub/64317/pg64317.cover.medium.jpg](https://www.gutenberg.org/cache/epub/64317/pg64317.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/64317/pg64317-images.html](https://www.gutenberg.org/cache/epub/64317/pg64317-images.html)'),(19,'As Aventuras de Tom Sawyer','Mark Twain','Aventura','\"As Aventuras de Tom Sawyer, Completas\", de Mark Twain, é um romance publicado em 1876 sobre um menino travesso que cresce às margens do rio Mississippi nas décadas de 1830 e 1840. Tom Sawyer e seu amigo Huckleberry Finn vivem aventuras infantis que tomam rumos cada vez mais perigosos quando testemunham um assassinato em um cemitério. Obrigados a guardar segredo e vivendo com medo, os meninos precisam decidir se devem ou não contar a verdade enquanto um homem inocente enfrenta um julgamento e um assassino vingativo permanece à solta.',1876,'[https://www.gutenberg.org/cache/epub/74/pg74.cover.medium.jpg](https://www.gutenberg.org/cache/epub/74/pg74.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/74/pg74-images.html](https://www.gutenberg.org/cache/epub/74/pg74-images.html)'),(20,'A Volta ao Mundo em Oitenta Dias','Jules Verne','Aventura','\"A Volta ao Mundo em Oitenta Dias\", de Júlio Verne, é um romance de aventura publicado em 1872. Quando o cavalheiro londrino Phileas Fogg aposta metade de sua fortuna que consegue dar a volta ao mundo em oitenta dias, ele embarca em uma corrida contra o tempo com seu criado francês, Passepartout. A jornada se complica quando um detetive confunde Fogg com um ladrão de bancos e os persegue através dos continentes. Ao longo do caminho, eles resgatam uma jovem e enfrentam inúmeros obstáculos que ameaçam seu prazo apertado.',1873,'https://www.gutenberg.org/cache/epub/103/pg103.cover.medium.jpg','https://www.gutenberg.org/cache/epub/103/pg103-images.html'),(21,'Vinte Mil Léguas Submarinas','Jules Verne','Ficção científica','\"Vinte Mil Léguas Submarinas\", de Júlio Verne, é um romance de ficção científica e aventura publicado em folhetim entre 1869 e 1870. Quando navios do mundo todo relatam encontros com um misterioso monstro marinho, uma expedição americana parte para destruí-lo. O professor Aronnax, o arpoador Ned Land e o criado Conseil descobrem que a criatura é, na verdade, um submarino futurista comandado pelo enigmático Capitão Nemo. Mantidos prisioneiros a bordo do Nautilus, eles embarcam em uma extraordinária jornada subaquática, testemunhando maravilhas e mistérios sob as ondas enquanto desvendam o passado sombrio de seu captor.',1869,'https://www.gutenberg.org/cache/epub/164/pg164.cover.medium.jpg','https://www.gutenberg.org/cache/epub/164/pg164-images.html'),(22,'O Chamado da Selva','Jack London','Aventura','\"O Chamado da Selva\", de Jack London, é um romance de aventura publicado em 1903. Buck, um cão poderoso que vive confortavelmente na Califórnia, é roubado e vendido para trabalhar como cão de trenó durante a Corrida do Ouro de Klondike. Arremessado na brutal região selvagem do Yukon, ele precisa lutar para sobreviver entre outros cães e mestres cruéis. À medida que Buck enfrenta o ambiente implacável, ele se torna cada vez mais primitivo, abandonando sua vida doméstica e respondendo a um chamado instinto ancestral que o atrai para algo selvagem e primitivo.',1903,'https://www.gutenberg.org/cache/epub/215/pg215.cover.medium.jpg','https://www.gutenberg.org/cache/epub/215/pg215-images.html'),(23,'O Conde de Monte Cristo','Alexandre Dumas','Romance','\"O Conde de Monte Cristo\", de Alexandre Dumas, é um romance de aventura publicado em folhetim de 1844 a 1846. Quando o marinheiro Edmond Dantès é falsamente acusado e preso no dia do seu casamento, ele passa quatorze anos em confinamento solitário. Após uma fuga ousada e a descoberta de um vasto tesouro escondido, ele se reinventa como o rico Conde de Monte Cristo. De volta a Paris, ele se infiltra metodicamente na alta sociedade para confrontar os três homens que destruíram sua vida, explorando temas como justiça, vingança, misericórdia e perdão.',1844,'https://www.gutenberg.org/cache/epub/1184/pg1184.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1184/pg1184-images.html'),(24,'Peter Pan','J. M. Barrie','Aventura','\"Peter Pan: [Peter e Wendy]\", de J. M. Barrie, é uma obra que começou como uma peça de teatro em 1904 e se tornou um romance em 1911. Conta a história de Peter Pan, um menino travesso que pode voar e nunca cresce. Ele leva Wendy Darling e seus irmãos para a Terra do Nunca, uma ilha mágica habitada por sereias, fadas e piratas. Lá, eles encontram os Meninos Perdidos e enfrentam o vilão Capitão Gancho, enquanto vivem aventuras que confundem a linha entre o encantamento infantil e o perigo.',1911,'https://www.gutenberg.org/cache/epub/16/pg16.cover.medium.jpg','https://www.gutenberg.org/cache/epub/16/pg16-images.html'),(25,'Frankenstein; or, the modern prometheus','Mary Wollstonecraft Shelley','Ficção científica','\"Frankenstein; Ou, O Moderno Prometeu\", de Mary Wollstonecraft Shelley, é um romance gótico publicado em 1818. Conta a história de Victor Frankenstein, um jovem cientista que cria uma criatura viva a partir de partes de corpos reunidas em um experimento heterodoxo. Quando a criatura desperta, Victor foge horrorizado, abandonando sua criação. O ser consciente precisa navegar em um mundo que o teme, aprendendo a linguagem e buscando conexão, apenas para enfrentar repetidas rejeições. Amargurado e sozinho, a criatura confronta seu criador com um pedido desesperado que os levará a um caminho sombrio de vingança e tragédia.',1818,'https://gutenberg.org/cache/epub/84/pg84.cover.medium.jpg','https://gutenberg.org/cache/epub/84/pg84-images.html'),(26,'O Fantasma da Ópera','Gaston Leroux','Terror','\"O Fantasma da Ópera\", de Gaston Leroux, é um romance de terror gótico publicado pela primeira vez entre 1909 e 1910. Ambientada na Ópera de Paris, a história acompanha eventos misteriosos envolvendo uma figura desfigurada conhecida como o Fantasma. Quando a jovem soprano Christine Daaé conquista sua obsessão, um perigoso triângulo amoroso surge entre Christine, o Fantasma e seu amor de infância, Raoul. À medida que as exigências do Fantasma se tornam mais sombrias e desesperadas, vidas ficam por um fio na casa de ópera.',1909,'https://www.gutenberg.org/cache/epub/62215/pg62215.cover.medium.jpg','https://www.gutenberg.org/cache/epub/62215/pg62215-images.html'),(27,'O Cão dos Baskervilles','Arthur Conan Doyle','Mistério','\"O Cão dos Baskervilles\", de Arthur Conan Doyle, é um romance policial publicado em série entre 1901 e 1902. Sherlock Holmes e Watson investigam uma lenda secular sobre um cão demoníaco que assombra a família Baskerville nos ermos de Dartmoor. Quando Sir Charles Baskerville morre em circunstâncias misteriosas, seu herdeiro, Sir Henry, chega do Canadá para reivindicar sua herança — apenas para se deparar com estranhas ameaças e perigos sobrenaturais. Holmes precisa determinar se a maldição é real ou se um assassino astuto se esconde por trás da lenda.',1902,'https://www.gutenberg.org/cache/epub/2852/pg2852.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2852/pg2852-images.html'),(28,'As Aventuras de Sherlock Holmes','Arthur Conan Doyle','Mistério','\"As Aventuras de Sherlock Holmes\", de Arthur Conan Doyle, é uma coletânea de contos publicada pela primeira vez em 1892. Essas doze histórias apresentam o lendário detetive Sherlock Holmes e seu companheiro, o Dr. Watson, narradas da perspectiva de Watson. Cada mistério explora injustiças sociais, ao mesmo tempo que demonstra os brilhantes métodos dedutivos de Holmes e sua abordagem não convencional à justiça. As histórias apresentam personagens e casos memoráveis que cativaram leitores por mais de um século, consagrando Holmes como um dos detetives mais duradouros da literatura.',1892,'https://www.gutenberg.org/cache/epub/1661/pg1661.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1661/pg1661-images.html'),(29,'A Inocência do Padre Brown','G. K. Chesterton','Mistério','\"A Inocência do Padre Brown\", de G. K. Chesterton, é uma coletânea de contos policiais escrita no início do século XX. O livro apresenta o Padre Brown, um humilde sacerdote inglês com um talento notável para solucionar mistérios, enquanto ele se depara com uma série de situações criminosas que frequentemente revelam lições morais profundas e complexidades humanas. No início do primeiro conto, \"A Cruz Azul\", somos apresentados ao Padre Brown através da perspectiva do formidável detetive francês Aristide Valentin, que está à caça do notório criminoso Flambeau. A narrativa cria uma atmosfera tensa e repleta de surpresas, culminando na revelação de que Brown é mais do que aparenta. Esse início envolvente prenuncia a mistura de humor, mistério e exploração filosófica que caracteriza toda a coleção, à medida que as observações perspicazes e o raciocínio não convencional do Padre Brown o levam a soluções inesperadas para os crimes que encontra.',1911,'https://www.gutenberg.org/cache/epub/204/pg204.cover.medium.jpg','https://www.gutenberg.org/cache/epub/204/pg204-images.html'),(30,'O Homem Invisível','H. G. Wells','Ficção Científica','\"O Homem Invisível: Um Romance Grotesco\", de H. G. Wells, é um romance de ficção científica publicado em 1897. Griffin, um cientista brilhante, descobre como se tornar invisível alterando o índice de refração do seu corpo. Mas, ao perceber que não consegue reverter o processo, seu isolamento e frustração o levam à loucura e à violência. Enquanto aterroriza uma aldeia inglesa e tenta escapar da captura, a busca desesperada de Griffin por poder o transforma em um fugitivo perigoso, caçado por autoridades cada vez mais desesperadas. Este influente romance explora as consequências sombrias da ambição desenfreada e o poder corruptor da invisibilidade.',1897,'[https://www.gutenberg.org/cache/epub/5230/pg5230.cover.medium.jpg](https://www.gutenberg.org/cache/epub/5230/pg5230.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/5230/pg5230-images.html](https://www.gutenberg.org/cache/epub/5230/pg5230-images.html)'),(31,'A Guerra dos Mundos','H. G. Wells','Ficção Científica','\"A Guerra dos Mundos\", de H. G. Wells, é um romance de ficção científica escrito entre 1895 e 1897. Quando marcianos com inteligência superior e armas avançadas invadem a Terra, a humanidade enfrenta a extinção. Os extraterrestres emergem de cilindros de metal, empunhando raios de calor devastadores e armas químicas tóxicas enquanto destroem metodicamente as defesas da Inglaterra. Um narrador anônimo luta para sobreviver à carnificina e se reunir com sua esposa enquanto a civilização desmorona ao seu redor. Uma das primeiras histórias de invasão alienígena, o romance de Wells explora a vulnerabilidade da humanidade diante de uma força imparável.',1898,'[https://www.gutenberg.org/cache/epub/36/pg36.cover.medium.jpg](https://www.gutenberg.org/cache/epub/36/pg36.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/36/pg36-images.html](https://www.gutenberg.org/cache/epub/36/pg36-images.html)'),(32,'A Ilha do Dr. Moreau','H. G. Wells','Ficção Científica','\"A Ilha do Dr. Moreau\", de H.G. Wells, é um romance de ficção científica publicado em 1896. O cientista náufrago Edward Prendick se vê preso em uma ilha remota habitada pelo Dr. Moreau, um fisiologista desonrado que realiza experimentos horríveis. Através da vivissecção, Moreau transforma animais em criaturas semelhantes a humanos, chamadas de Povo-Fera, que lutam para manter sua humanidade sob um rígido código de leis. À medida que Prendick descobre os segredos sombrios da ilha, ele aborda questões sobre os limites da ciência, a natureza da identidade humana e o preço da ambição desenfreada.',1896,'[https://www.gutenberg.org/cache/epub/159/pg159.cover.medium.jpg](https://www.gutenberg.org/cache/epub/159/pg159.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/159/pg159-images.html](https://www.gutenberg.org/cache/epub/159/pg159-images.html)'),(33,'Contos de Fadas dos Irmãos Grimm','Jacob Grimm e Wilhelm Grimm','Fantasia','\"Contos de Fadas dos Irmãos Grimm\", de Jacob Grimm e Wilhelm Grimm, é uma coletânea alemã de contos de fadas publicada pela primeira vez em 1812. Começando com 86 histórias e expandindo-se para 210 contos em sete edições, esta obra seminal transformou o folclore oral em literatura escrita. Os irmãos coletaram histórias de amigos, conhecidos e livros antigos para preservar a história cultural alemã. O que começou como um projeto acadêmico evoluiu ao longo de décadas de revisões, com contos adicionados e removidos, conteúdo adaptado para jovens leitores e ilustrações incorporadas, tornando-se um pilar da literatura infantil ocidental.',1812,'[https://www.gutenberg.org/cache/epub/2591/pg2591.cover.medium.jpg](https://www.gutenberg.org/cache/epub/2591/pg2591.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/2591/pg2591-images.html](https://www.gutenberg.org/cache/epub/2591/pg2591-images.html)'),(34,'As Mil e Uma Noites','Stanley Lane-Poole','Fantasia','\"As Mil e Uma Noites, Vol. I\", de Lane, Lane-Poole, Poole e Harvey, é uma coleção de contos populares do Oriente Médio compilados durante a Era de Ouro Islâmica. Um rei desesperado executa noivas virgens todas as manhãs, até que a astuta Sherazade se salva através da arte de contar histórias, tecendo contos a cada noite que terminam em suspense. Suas histórias abrangem narrativas históricas, histórias de amor e aventuras com gênios, feiticeiros e lugares lendários — cada uma delas lhe concedendo mais um dia de vida ao longo de mil e uma noites.',1885,'[https://www.gutenberg.org/cache/epub/34206/pg34206.cover.medium.jpg](https://www.gutenberg.org/cache/epub/34206/pg34206.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/34206/pg34206-images.html](https://www.gutenberg.org/cache/epub/34206/pg34206-images.html)'),(35,'Crime e Castigo','Fyodor Dostoyevsky','Romance','\"Crime e Castigo\", de Fiódor Dostoiévski, é um romance publicado em 1866. A história acompanha Rodion Raskólnikov, um ex-estudante de direito empobrecido em São Petersburgo, que planeja assassinar um agiota inescrupuloso. Ele se convence de que certos crimes são justificáveis se cometidos por homens \"extraordinários\" em busca de objetivos mais elevados. Uma vez consumado o ato, porém, ele é consumido pela confusão, paranoia e culpa, à medida que suas justificativas teóricas desmoronam e ele enfrenta as consequências internas e externas de suas ações.',1886,'[https://www.gutenberg.org/cache/epub/2554/pg2554.cover.medium.jpg](https://www.gutenberg.org/cache/epub/2554/pg2554.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/2554/pg2554-images.html](https://www.gutenberg.org/cache/epub/2554/pg2554-images.html)'),(36,'O Retrato de Dorian Gray','Oscar Wilde','Terror','\"O Retrato de Dorian Gray\", de Oscar Wilde, é um romance filosófico e de terror gótico publicado em 1890. Quando um belo jovem deseja que seu retrato envelheça em seu lugar, seu desejo se torna terrivelmente real. Enquanto Dorian busca uma vida de prazeres e corrupção moral, ele permanece eternamente jovem, enquanto sua imagem pintada se transforma em um registro horripilante de seus pecados. Wilde explora a beleza, a moralidade e a influência perigosa desta história sobre a filosofia hedonista, a vaidade e suas consequências.',1890,'[https://www.gutenberg.org/cache/epub/174/pg174.cover.medium.jpg](https://www.gutenberg.org/cache/epub/174/pg174.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/174/pg174-images.html](https://www.gutenberg.org/cache/epub/174/pg174-images.html)'),(37,'Dom Quixote','Miguel de Cervantes Saavedra','Romance','\"Dom Quixote\", de Miguel de Cervantes Saavedra, é um romance espanhol publicado em 1605. Um nobre de baixa patente perde a sanidade por ler muitos romances de cavalaria e decide tornar-se um cavaleiro andante. Renomeando-se Dom Quixote, ele recruta um simples camponês, Sancho Pança, como seu escudeiro. Juntos, eles embarcam em aventuras onde Dom Quixote confunde moinhos de vento com gigantes e estalagens com castelos, incapaz de enxergar o mundo como ele realmente é.',1605,'[https://www.gutenberg.org/cache/epub/5921/pg5921.cover.medium.jpg](https://www.gutenberg.org/cache/epub/5921/pg5921.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/5921/pg5921-images.html](https://www.gutenberg.org/cache/epub/5921/pg5921-images.html)'),(38,'Anna Kariênina','Liev Tolstói','Romance','\"Anna Karenina\", de Liev Tolstói, é um romance publicado pela primeira vez em 1878. A história acompanha Anna, uma socialite casada da Rússia Imperial, cujo caso extraconjugal com o oficial de cavalaria Conde Vronsky escandaliza São Petersburgo e os força a fugir para a Itália. Uma narrativa paralela acompanha a busca pelo casamento do proprietário de terras Konstantin Levin e seus conflitos com a fé e a administração de sua propriedade. O romance explora temas como traição, família, casamento, desejo e o choque entre a vida rural e urbana em meio à rápida transformação social da Rússia.',1878,'[https://www.gutenberg.org/cache/epub/1399/pg1399.cover.medium.jpg](https://www.gutenberg.org/cache/epub/1399/pg1399.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/1399/pg1399-images.html](https://www.gutenberg.org/cache/epub/1399/pg1399-images.html)'),(39,'A Divina Comédia','Dante Alighieri','Poesia','\"A Divina Comédia\", de Dante Alighieri, é um poema narrativo italiano escrito entre 1308 e 1321. A obra acompanha a jornada de Dante pelos três reinos da vida após a morte: Inferno, Purgatório e Paraíso. Guiado pelo poeta Virgílio e sua idealizada Beatriz, Dante encontra almas que recebem justiça divina com base em suas ações terrenas. O poema representa alegoricamente a jornada da alma em direção a Deus através do reconhecimento do pecado, da penitência e da ascensão espiritual, baseando-se em teologia e filosofia católica medieval.',1321,'[https://www.gutenberg.org/cache/epub/8800/pg8800.cover.medium.jpg](https://www.gutenberg.org/cache/epub/8800/pg8800.cover.medium.jpg)','[https://www.gutenberg.org/cache/epub/8800/pg8800-images.html](https://www.gutenberg.org/cache/epub/8800/pg8800-images.html)'),(50,'O Segredo das Chaminés','Agatha Christie','Crime / Mistério','\"O Segredo das Chaminés\", de Agatha Christie, é um romance policial repleto de suspense, escrito no início do século XX. A história apresenta Anthony Cade, que se envolve em uma teia de intrigas envolvendo segredos da realeza, chantagem, pessoas desaparecidas e uma possível restauração da monarquia em uma nação balcânica fictícia. Ao aceitar entregar um manuscrito de memórias a uma editora em Londres, Anthony acaba envolvido em perigosas conspirações e confrontos com diversas facções.',1925,'https://www.gutenberg.org/cache/epub/65238/pg65238.cover.medium.jpg','https://www.gutenberg.org/cache/epub/65238/pg65238-images.html'),(51,'As Extraordinárias Aventuras de Arsène Lupin','Maurice Leblanc','Aventura / Crime','\"As Extraordinárias Aventuras de Arsène Lupin, o Cavalheiro-Ladrão\", de Maurice Leblanc, é uma coletânea de contos publicada em 1907. A obra apresenta Arsène Lupin, um mestre ladrão extremamente habilidoso que engana a polícia e a alta sociedade. Ao longo das histórias, ele realiza roubos ousados, utiliza disfarces engenhosos e protagoniza fugas audaciosas.',1907,'https://www.gutenberg.org/cache/epub/6133/pg6133.cover.medium.jpg','https://www.gutenberg.org/cache/epub/6133/pg6133-images.html'),(52,'Os Mistérios de Udolpho','Ann Radcliffe','Mistério / Terror gótico','\"Os Mistérios de Udolpho\", de Ann Radcliffe, é um romance gótico publicado em 1794. A jovem Emily St. Aubert enfrenta diversos infortúnios após a morte de seus pais e acaba presa em um castelo italiano controlado pelo ameaçador Montoni. Cercada por segredos, fenômenos sobrenaturais e perigos misteriosos, Emily precisa enfrentar intrigas enquanto permanece separada de seu amado Valancourt.',1794,'https://www.gutenberg.org/cache/epub/3268/pg3268.cover.medium.jpg','https://www.gutenberg.org/cache/epub/3268/pg3268-images.html'),(53,'Carmem','Prosper Mérimée','Romance / Drama','\"Carmen\", de Prosper Mérimée, é uma novela publicada em 1845. A narrativa acompanha Carmen, uma mulher independente cuja personalidade e recusa em ser controlada despertam ciúme, violência e paixão. A história de Dom José e Carmen apresenta uma trajetória marcada por amor, destino e tragédia.',1845,'https://www.gutenberg.org/cache/epub/2465/pg2465.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2465/pg2465-images.html'),(54,'A Múmia Verde','Fergus Hume','Mistério / Crime','\"A Múmia Verde\", de Fergus Hume, é um romance de mistério que acompanha Archie Hope e Lucy Kendal em meio a uma história de romance e intriga. A trama envolve uma rara múmia peruana adquirida pelo professor Braddock, padrasto de Lucy, cuja obsessão pela arqueologia acaba levando a acontecimentos misteriosos e perigosos.',1908,'https://www.gutenberg.org/cache/epub/2868/pg2868.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2868/pg2868-images.html'),(55,'O Homem que Era Quinta-Feira','G. K. Chesterton','Mistério / Suspense','\"O Homem que Era Quinta-Feira: Um Pesadelo\", de G. K. Chesterton, acompanha Gabriel Syme, um detetive da polícia que se infiltra em um grupo de anarquistas em Londres para descobrir seus planos. A narrativa mistura aventura, sátira e reflexão filosófica sobre ordem, caos e a natureza do mal, utilizando situações absurdas e diálogos espirituosos.',1908,'https://www.gutenberg.org/cache/epub/1695/pg1695.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1695/pg1695-images.html'),(56,'Dr. Jekyll e Mr. Hyde','Robert Louis Stevenson','Terror / Ficção psicológica','\"O Estranho Caso do Dr. Jekyll e do Sr. Hyde\", de Robert Louis Stevenson, é uma novela de terror gótico publicada em 1886. O advogado Gabriel John Utterson investiga acontecimentos estranhos envolvendo seu amigo, o Dr. Henry Jekyll, e o criminoso Edward Hyde. A obra explora a dualidade da natureza humana e o conflito entre as aparências respeitáveis e os desejos ocultos.',1886,'https://www.gutenberg.org/cache/epub/43/pg43.cover.medium.jpg','https://www.gutenberg.org/cache/epub/43/pg43-images.html'),(57,'O Mistério de Edwin Drood','Charles Dickens','Mistério / Crime','\"O Mistério de Edwin Drood\", de Charles Dickens, é um romance publicado em 1870. A última obra inacabada de Dickens acompanha John Jasper, mestre de coro de uma catedral e usuário de ópio, que deseja sua aluna Rosa Bud, noiva de seu sobrinho Edwin Drood. Quando Edwin desaparece misteriosamente, suspeitas recaem sobre seu rival Neville Landless. O mistério permanece sem solução devido à morte de Dickens antes da conclusão da obra.',1870,'https://www.gutenberg.org/cache/epub/564/pg564.cover.medium.jpg','https://www.gutenberg.org/cache/epub/564/pg564-images.html'),(58,'O Rei de Amarelo','Robert W. Chambers','Terror / Mistério','\"O Rei de Amarelo\", de Robert W. Chambers, é uma coletânea de contos publicada em 1895. As primeiras histórias são interligadas por uma peça proibida que leva seus leitores à loucura. Uma entidade misteriosa, o Rei de Amarelo, e o sinistro Sinal Amarelo aparecem em histórias marcadas pelo terror sobrenatural, pelo mistério e pelo desconhecido.',1895,'https://www.gutenberg.org/cache/epub/8492/pg8492.cover.medium.jpg','https://www.gutenberg.org/cache/epub/8492/pg8492-images.html'),(59,'Um Estudo em Vermelho','Arthur Conan Doyle','Crime / Mistério','\"Um Estudo em Vermelho\", de Arthur Conan Doyle, é um romance policial publicado em 1887. A obra apresenta Sherlock Holmes e Dr. Watson enquanto investigam um misterioso assassinato em Londres. Quando um homem é encontrado morto com a palavra \"RACHE\" escrita em sangue, Holmes precisa desvendar uma investigação que envolve vingança e acontecimentos ocorridos décadas antes em Utah.',1887,'https://www.gutenberg.org/cache/epub/244/pg244.cover.medium.jpg','https://www.gutenberg.org/cache/epub/244/pg244-images.html'),(60,'As Obras de Edgar Allan Poe — Volume 1','Edgar Allan Poe','Terror / Mistério','\"As Obras de Edgar Allan Poe — Volume 1\", de Edgar Allan Poe, é uma coletânea que reúne diferentes obras do autor. O volume apresenta contos e textos relacionados aos gêneros de terror, mistério e poesia, explorando temas como melancolia, sobrenatural, desespero e complexidade da natureza humana.',1900,'https://www.gutenberg.org/cache/epub/2147/pg2147.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2147/pg2147-images.html'),(61,'As Obras de Edgar Allan Poe — Volume 2','Edgar Allan Poe','Terror / Mistério','\"As Obras de Edgar Allan Poe — Volume 2\", de Edgar Allan Poe, é uma coletânea de contos e ensaios que explora mistério, horror e o inexplicável. Entre os textos está \"A Carta Roubada\", que acompanha o detetive C. Auguste Dupin em uma investigação envolvendo uma carta desaparecida de grande importância política.',1900,'https://www.gutenberg.org/cache/epub/2148/pg2148.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2148/pg2148-images.html'),(62,'A Volta do Parafuso','Henry James','Terror psicológico','\"A Volta do Parafuso\", de Henry James, é uma novela de terror gótico publicada em 1898. Uma jovem governanta chega a uma propriedade rural isolada para cuidar de duas crianças, mas começa a acreditar que forças sobrenaturais assombram o local. Conforme testemunha figuras misteriosas e observa o comportamento das crianças, a diferença entre realidade e imaginação se torna cada vez mais incerta.',1898,'https://www.gutenberg.org/cache/epub/209/pg209.cover.medium.jpg','https://www.gutenberg.org/cache/epub/209/pg209-images.html'),(63,'O Assassinato de Roger Ackroyd','Agatha Christie','Crime / Mistério','\"O Assassinato de Roger Ackroyd\", de Agatha Christie, é um romance policial publicado em 1926. Quando Roger Ackroyd é encontrado morto em seu escritório, o detetive Hercule Poirot é chamado para investigar. A investigação revela uma complexa rede de segredos, chantagens e suspeitos, conduzindo a uma das conclusões mais inovadoras da literatura policial.',1926,'https://www.gutenberg.org/cache/epub/69087/pg69087.cover.medium.jpg','https://www.gutenberg.org/cache/epub/69087/pg69087-images.html'),(64,'O Signo dos Quatro','Arthur Conan Doyle','Crime / Mistério','\"O Signo dos Quatro\", de Arthur Conan Doyle, é um romance policial publicado em 1890. Mary Morstan procura Sherlock Holmes para investigar o desaparecimento de seu pai e os misteriosos presentes de pérolas que recebe anualmente. A investigação leva Holmes e Watson a um tesouro escondido, assassinatos e uma conspiração que se estende da Índia até Londres.',1890,'https://www.gutenberg.org/cache/epub/2097/pg2097.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2097/pg2097-images.html'),(65,'O Chamado de Cthulhu','H. P. Lovecraft','Terror','\"O Chamado de Cthulhu\", de H. P. Lovecraft, é um conto de terror cósmico escrito em 1926 e publicado em 1928. Francis Wayland Thurston investiga as anotações misteriosas de seu tio-avô e descobre informações sobre sonhos perturbadores, cultos ancestrais e uma entidade monstruosa chamada Cthulhu.',1928,'https://www.gutenberg.org/cache/epub/68283/pg68283.cover.medium.jpg','https://www.gutenberg.org/cache/epub/68283/pg68283-images.html'),(66,'As Memórias de Sherlock Holmes','Arthur Conan Doyle','Mistério / Policial','\"As Memórias de Sherlock Holmes\", de Arthur Conan Doyle, é uma coletânea de contos publicada em 1893. A obra apresenta doze casos envolvendo Sherlock Holmes e Dr. Watson, incluindo investigações sobre cavalos desaparecidos, tratados navais e outros mistérios da Inglaterra vitoriana.',1893,'https://www.gutenberg.org/cache/epub/834/pg834.cover.medium.jpg','https://www.gutenberg.org/cache/epub/834/pg834-images.html'),(67,'O Retorno de Sherlock Holmes','Arthur Conan Doyle','Mistério / Policial','\"O Retorno de Sherlock Holmes\", de Arthur Conan Doyle, é uma coletânea de contos publicada em 1905. Após a aparente morte de Holmes, a enorme pressão dos leitores levou ao retorno do personagem. Os novos casos envolvem códigos, pessoas desaparecidas e criminosos perigosos na Inglaterra vitoriana.',1905,'https://www.gutenberg.org/cache/epub/108/pg108.cover.medium.jpg','https://www.gutenberg.org/cache/epub/108/pg108-images.html'),(68,'Moby Dick; ou, A Baleia','Herman Melville','Aventura','\"Moby Dick; ou, A Baleia\", de Herman Melville, é um romance épico publicado em 1851. O marinheiro Ismael narra a perseguição obsessiva do Capitão Ahab a Moby Dick, uma gigantesca baleia que destruiu sua perna. A busca por vingança leva o navio Pequod e sua tripulação pelos oceanos, explorando temas como destino, natureza humana, bem e mal.',1851,'https://www.gutenberg.org/cache/epub/2701/pg2701.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2701/pg2701-images.html'),(69,'A Odisseia','Homero','Aventura / Épico','A \"Odisseia\", de Homero, é uma epopeia da Grécia Antiga que acompanha Odisseu em sua perigosa jornada de dez anos de volta para casa após a Guerra de Troia. Enquanto enfrenta monstros e perde seus companheiros, sua esposa Penélope e seu filho Telêmaco enfrentam pretendentes que acreditam que ele está morto. A obra explora temas como retorno ao lar, lealdade, perseverança e aventura.',1488,'https://www.gutenberg.org/cache/epub/1727/pg1727.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1727/pg1727-images.html'),(70,'Romeu e Julieta','William Shakespeare','Drama / Romance','\"Romeu e Julieta\", de William Shakespeare, é uma tragédia escrita entre 1591 e 1595. Dois jovens de famílias rivais se apaixonam secretamente em Verona e se casam com a ajuda de um frade, esperando unir suas famílias. Entretanto, o ódio familiar, os duelos e os mal-entendidos conduzem a uma sequência de acontecimentos trágicos.',1597,'https://www.gutenberg.org/cache/epub/1513/pg1513.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1513/pg1513-images.html'),(71,'Razão e Sensibilidade','Jane Austen','Romance','\"Razão e Sensibilidade\", de Jane Austen, é um romance publicado em 1811. As irmãs Dashwood enfrentam dificuldades financeiras e emocionais enquanto lidam com amor e desilusão. Elinor representa a prudência e a sensatez, enquanto Marianne segue a paixão e a sensibilidade, enfrentando expectativas sociais e conflitos amorosos.',1811,'https://www.gutenberg.org/cache/epub/21839/pg21839.cover.medium.jpg','https://www.gutenberg.org/cache/epub/21839/pg21839-images.html'),(72,'Middlemarch','George Eliot','Romance','\"Middlemarch\", de George Eliot, é um romance publicado entre 1871 e 1872. Ambientado em uma cidade fictícia da Inglaterra, o livro entrelaça diferentes histórias envolvendo amor, casamento, idealismo, dívidas, ambições profissionais e mudanças sociais. A narrativa acompanha personagens que buscam propósito e realização em meio às transformações políticas e sociais.',1872,'https://www.gutenberg.org/cache/epub/145/pg145.cover.medium.jpg','https://www.gutenberg.org/cache/epub/145/pg145-images.html'),(73,'O Castelo Azul','L. M. Montgomery','Romance','\"O Castelo Azul\", de L. M. Montgomery, é um romance publicado em 1926. Valancy Stirling passou a vida sufocada pelas expectativas de sua família. Após receber uma notícia médica que muda sua perspectiva, decide abandonar as limitações impostas a ela e viver de acordo com suas próprias escolhas, iniciando uma nova vida ao lado de Barney Snaith.',1926,'https://www.gutenberg.org/cache/epub/67979/pg67979.cover.medium.jpg','https://www.gutenberg.org/cache/epub/67979/pg67979-images.html'),(74,'Manon Lescaut','Abade Prévost','Romance / Drama','\"Manon Lescaut\", de Abbé Prévost, é um romance publicado em 1731. A obra narra a história trágica de um jovem nobre e uma mulher de origem humilde que decidem viver juntos, enfrentando uma trajetória marcada por paixão, jogos, fraudes, crimes, prisão e exílio. Narrada retrospectivamente, a história explora paixão, escolhas e consequências.',1731,'https://www.gutenberg.org/cache/epub/468/pg468.cover.medium.jpg','https://www.gutenberg.org/cache/epub/468/pg468-images.html'),(75,'O Monge','M. G. Lewis','Terror gótico','\"O Monge: Um Romance\", de M. G. Lewis, é um romance gótico publicado em 1796. A história acompanha Ambrosio, um monge que sucumbe a desejos proibidos quando uma figura misteriosa se infiltra em seu mosteiro. Sua queda transforma sua vida em uma trama marcada por luxúria, assassinato e elementos sobrenaturais.',1796,'https://www.gutenberg.org/cache/epub/601/pg601.cover.medium.jpg','https://www.gutenberg.org/cache/epub/601/pg601-images.html'),(76,'A Dama do Lago','Walter Scott','Aventura / Romance','\"A Dama do Lago\", de Walter Scott, é um poema narrativo publicado originalmente em 1810. Ambientado nas Terras Altas da Escócia, a obra entrelaça uma rivalidade amorosa, conflitos políticos e uma guerra iminente entre diferentes regiões. A narrativa explora amor, lealdade e antigas rivalidades.',1810,'https://www.gutenberg.org/cache/epub/3011/pg3011.cover.medium.jpg','https://www.gutenberg.org/cache/epub/3011/pg3011-images.html'),(77,'Rei Arthur e os Cavaleiros da Távola Redonda','Thomas Malory','Aventura','\"O Rei Arthur e os Cavaleiros da Távola Redonda\", de Sir Thomas Malory, é uma compilação em prosa escrita por volta de 1470. A obra reúne histórias lendárias de Arthur, Guinevere, Lancelot, Merlin e os Cavaleiros da Távola Redonda, incluindo a busca pelo Santo Graal e a lenda de Tristão e Isolda.',1470,'https://www.gutenberg.org/cache/epub/36462/pg36462.cover.medium.jpg','https://www.gutenberg.org/cache/epub/36462/pg36462-images.html'),(78,'Thuvia, criada de Marte','Edgar Rice Burroughs','Aventura / Ficção científica','\"Thuvia, Donzela de Marte\", de Edgar Rice Burroughs, é um romance de ficção científica e fantasia. A história acompanha Carthoris, filho de John Carter, que ama a princesa Thuvia de Ptarth. Quando ela é sequestrada e Carthoris é acusado, ele parte em uma missão de resgate que envolve guerras e perigos em Marte.',1920,'https://www.gutenberg.org/cache/epub/72/pg72.cover.medium.jpg','https://www.gutenberg.org/cache/epub/72/pg72-images.html'),(79,'A Lagoa Azul','H. De Vere Stacpoole','Aventura / Romance','\"A Lagoa Azul: Um Romance\", de H. De Vere Stacpoole, é um romance de formação publicado em 1908. Dois jovens primos naufragam em uma ilha remota do Pacífico Sul e precisam sobreviver sozinhos após a morte de seu cuidador. Crescendo isolados, descobrem os mistérios da natureza, da maturidade e do amor.',1908,'https://www.gutenberg.org/cache/epub/393/pg393.cover.medium.jpg','https://www.gutenberg.org/cache/epub/393/pg393-images.html'),(80,'Vinte Anos Depois','Alexandre Dumas','Aventura','\"Vinte Anos Depois\", de Alexandre Dumas e Auguste Maquet, é um romance publicado em folhetim entre janeiro e agosto de 1845. D’Artagnan, agora tenente, é convocado para reunir os antigos mosqueteiros em meio à turbulência política da França e da Inglaterra. Os quatro amigos precisam enfrentar conflitos de lealdade e deixar suas diferenças de lado para uma nova missão.',1845,'https://www.gutenberg.org/cache/epub/1259/pg1259.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1259/pg1259-images.html'),(81,'Catriona','Robert Louis Stevenson','Aventura','\"Catriona\", de Robert Louis Stevenson, é um romance publicado em 1893 e sequência de \"Sequestrado\". David Balfour busca justiça para um homem injustamente acusado de assassinato na Escócia do século XVIII. Durante sua jornada, conhece Catriona Drummond, filha de um fora da lei escocês, e se envolve em aventuras, conspirações e conflitos políticos.',1893,'https://www.gutenberg.org/cache/epub/589/pg589.cover.medium.jpg','https://www.gutenberg.org/cache/epub/589/pg589-images.html'),(82,'Um Quarto com Vista','E. M. Forster','Romance','\"Um Quarto com Vista\", de E. M. Forster, é um romance publicado em 1908. A jovem Lucy Honeychurch viaja para a Itália com sua prima rígida como acompanhante, onde um encontro inesperado com o excêntrico George Emerson desperta emoções confusas. De volta à Inglaterra, Lucy fica noiva do sofisticado, porém pomposo, Cecil Vyse. Quando os Emersons se mudam para perto, Lucy precisa confrontar seus verdadeiros sentimentos e decidir entre as expectativas da sociedade e a paixão genuína na cultura contida da Inglaterra eduardiana.',1908,'https://www.gutenberg.org/cache/epub/2641/pg2641.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2641/pg2641-images.html'),(83,'Adeus às Armas','Ernest Hemingway','Romance / Drama','\"Adeus às Armas\", de Ernest Hemingway, é um romance publicado pela primeira vez em 1929. Ambientado durante a campanha italiana da Primeira Guerra Mundial, o livro acompanha o tenente americano Frederic Henry, que serve no corpo de ambulâncias italiano. Quando ele conhece a enfermeira inglesa Catherine Barkley, um romance apaixonado floresce em meio ao cenário brutal da guerra. À medida que a batalha se intensifica e o relacionamento se aprofunda, os amantes enfrentam escolhas devastadoras que testarão se o seu vínculo pode sobreviver ao caos que os cerca.',1929,'https://www.gutenberg.org/cache/epub/75201/pg75201.cover.medium.jpg','https://www.gutenberg.org/cache/epub/75201/pg75201-images.html'),(84,'O Pirata','Walter Scott','Aventura / Romance','\"O Pirata\", de Walter Scott, é um romance publicado em 1821. Ambientado nas Ilhas Shetland no final do século XVII, conta a história do jovem Mordaunt, cuja amizade com as irmãs Troil é abalada pela chegada de um misterioso capitão náufrago chamado Cleveland. À medida que a rivalidade entre os dois homens cresce, Minna se apaixona pelo carismático forasteiro, sem saber de seu sombrio segredo. Quando piratas capturam as irmãs Troil, identidades ocultas são reveladas e lealdades são postas à prova nesta história de romance e aventura.',1821,'https://www.gutenberg.org/cache/epub/42389/pg42389.cover.medium.jpg','https://www.gutenberg.org/cache/epub/42389/pg42389-images.html'),(85,'Lorna Doone','R. D. Blackmore','Aventura / Romance','\"Lorna Doone: Um Romance de Exmoor\", de R. D. Blackmore, é um romance publicado em 1869. Ambientado em Devon e Somerset, no século XVII, acompanha John Ridd, um fazendeiro cujo pai foi assassinado pelo clã fora da lei Doone. Quando John se apaixona por Lorna, que aparenta ser uma Doone, ele se vê diante de uma escolha impossível entre vingança e devoção. À medida que segredos sobre a verdadeira identidade de Lorna vêm à tona e uma rebelião política varre a Inglaterra, o amor deles enfrenta obstáculos mortais que ameaçam destruí-los.',1869,'https://www.gutenberg.org/cache/epub/17460/pg17460.cover.medium.jpg','https://www.gutenberg.org/cache/epub/17460/pg17460-images.html'),(86,'O Tesouro das Pérolas','Gustave Aimard','Aventura','\"O Tesouro das Pérolas: Um Romance de Aventuras na Califórnia\", de Gustave Aimard, é um romance histórico escrito em meados do século XIX. Ambientado nas vastas e muitas vezes perigosas paisagens da Califórnia e do México, o enredo gira em torno de temas como aventura, romance e sobrevivência. A narrativa acompanha Benito Vázquez de Bustamente e Dolores enquanto enfrentam encontros traiçoeiros, bandidos e perigos da natureza selvagem em busca de tesouros e justiça.',1863,'https://www.gutenberg.org/cache/epub/46276/pg46276.cover.medium.jpg','https://www.gutenberg.org/cache/epub/46276/pg46276-images.html'),(87,'O Andarilho: O Romance de um Homem a Pé','Holman Day','Aventura / Reflexão','\"O Andarilho: O Romance de um Homem a Pé\", de Holman Day, é um romance escrito no início do século XX. A história acompanha Walker Farr, um jovem que viaja a pé por uma estrada rural, personificando a essência de um andarilho sem destino fixo. Suas aventuras e interações revelam sua visão de mundo e temas como individualidade versus normas sociais, simplicidade da vida e expectativas sociais.',1915,'https://www.gutenberg.org/cache/epub/4712/pg4712.cover.medium.jpg','https://www.gutenberg.org/cache/epub/4712/pg4712-images.html'),(88,'O Motorista de Cynthia','Louis Tracy','Romance / Mistério','\"O Motorista de Cynthia\", de Louis Tracy, é um romance escrito no início do século XX. A história se desenrola no dia do Derby, em Londres, e apresenta Cynthia Vanrenen e sua acompanhante inglesa, a Sra. Devar. Quando o motorista delas sofre um acidente, o jovem Lorde Medenham decide assumir o volante, disfarçando-se de motorista. A história mistura romance, humor, aventura e diferenças de classe.',1910,'https://www.gutenberg.org/cache/epub/49987/pg49987.cover.medium.jpg','https://www.gutenberg.org/cache/epub/31472/pg31472-images.html'),(89,'O Lírio Vermelho','Anatole France','Romance / Drama','\"O Lírio Vermelho — Completo\", de Anatole France, é um romance publicado em 1894. Conta a história de uma bela condessa francesa presa em um casamento sem amor, que se envolve com dois homens e posteriormente descobre uma verdadeira paixão por um escultor. Quando seu antigo caso vem à tona, o ciúme ameaça destruir o amor que ela mais preza. Ambientado em Florença e Paris, o drama explora amor, verdade e perdão.',1894,'https://www.gutenberg.org/cache/epub/3922/pg3922.cover.medium.jpg','https://www.gutenberg.org/cache/epub/3922/pg3922-images.html'),(90,'Camille (A Dama das Camélias)','Alexandre Dumas','Romance / Drama','\"Camille (La Dame aux Camélias)\", de Alexandre Dumas, é um romance publicado pela primeira vez em 1848. A história semi-autobiográfica narra o romance trágico entre Marguerite Gautier, uma cortesã parisiense que sofre de tuberculose, e Armand Duval, um jovem burguês que se apaixona profundamente por ela. A narrativa explora amor proibido, sacrifício e as rígidas convenções da sociedade francesa do século XIX.',1848,'https://www.gutenberg.org/cache/epub/1608/pg1608.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1608/pg1608-images.html'),(91,'Um Par de Olhos Azuis','Thomas Hardy','Romance / Drama','\"Um Par de Olhos Azuis\", de Thomas Hardy, é um romance escrito no final do século XIX. A obra explora temas como amor e classe social através das experiências de Elfride Swancourt, uma jovem que lida com suas emoções e relacionamentos em um ambiente rural inglês. O início da narrativa apresenta Elfride e sua expectativa pela chegada de Stephen Smith, um jovem arquiteto enviado para supervisionar a restauração de uma igreja local.',1873,'https://www.gutenberg.org/cache/epub/224/pg224.cover.medium.jpg','https://www.gutenberg.org/cache/epub/224/pg224-images.html'),(92,'O Romance de Tristão e Isolda','Joseph Bédier','Romance / Aventura','\"O Romance de Tristão e Isolda\", de Joseph Bédier, é um conto medieval clássico recontado em prosa. Esta história atemporal de amor trágico acompanha os corações do nobre Tristão e da bela Isolda, enquanto seu romance predestinado se desenrola em meio a temas de lealdade, dever e traição. A narrativa apresenta cavaleiros, reinos, amor proibido, ciúme e engano.',1900,'https://www.gutenberg.org/cache/epub/14244/pg14244.cover.medium.jpg','https://www.gutenberg.org/cache/epub/14244/pg14244-images.html'),(93,'Humores','Louisa May Alcott','Romance / Drama','\"Humores\", de Louisa May Alcott, é um romance publicado em 1864. A jovem Sylvia Yule vivencia a transição da infância para a vida adulta, dividida entre dois homens: Geoffrey Moor, a quem considera um amigo querido, e Adam Warwick, por quem se apaixona perdidamente. Sua luta entre o dever e o desejo se desenrola como uma reflexão sobre casamento, independência e os humores imprevisíveis do coração.',1864,'https://www.gutenberg.org/cache/epub/28203/pg28203.cover.medium.jpg','https://www.gutenberg.org/cache/epub/28203/pg28203-images.html'),(94,'Doutor Cupido','Rhoda Broughton','Romance / Comédia','\"Doutor Cupido: Um Romance\", de Rhoda Broughton, é uma obra de ficção provavelmente escrita no final do século XIX. O romance apresenta a vida das irmãs Lambton, com foco especial em Peggy e Prue, que vivenciam suas experiências e envolvimentos românticos enquanto enfrentam as expectativas sociais e os desejos pessoais.',1886,'https://www.gutenberg.org/cache/epub/2825/pg2825.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2825/pg2825-images.html'),(95,'Amor de uma Garota','Charles Garvice','Romance','\"Only a Girl\'s Love\", de Charles Garvice, é um romance provavelmente escrito no final do século XIX. A história gira em torno de Stella, uma jovem que busca refúgio com seu tio James Etheridge após fugir de uma escola rígida. A narrativa explora temas como amor, família e realização pessoal, enquanto Stella conhece novas pessoas e começa a enfrentar seus próprios sentimentos.',1887,'https://www.gutenberg.org/cache/epub/53416/pg53416.cover.medium.jpg','https://www.gutenberg.org/cache/epub/53416/pg53416-images.html'),(96,'Meditações','Marco Aurélio','Reflexão','\"Meditações\", do Imperador Romano Marco Aurélio, é uma série de escritos pessoais compostos entre 170 e 180 d.C. Escrita em grego como anotações particulares, a obra captura reflexões sobre a filosofia estoica, o aprimoramento pessoal, princípios éticos e a busca pela harmonia interior por meio da razão.',1559,'https://www.gutenberg.org/cache/epub/2680/pg2680.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2680/pg2680-images.html'),(97,'Autobiografia de Benjamin Franklin','Benjamin Franklin','Biografia / Reflexão','\"Autobiografia de Benjamin Franklin\", de Benjamin Franklin, é uma autobiografia inacabada escrita entre 1771 e 1790. Franklin narra sua trajetória desde jovem aprendiz até se tornar um impressor de sucesso e líder cívico na Filadélfia. A obra apresenta seu projeto de alcançar a perfeição moral por meio de treze virtudes, revelando suas lutas e filosofias.',1791,'https://www.gutenberg.org/cache/epub/20203/pg20203.cover.medium.jpg','https://www.gutenberg.org/cache/epub/20203/pg20203-images.html'),(98,'Narrativa da Vida de Frederick Douglass','Frederick Douglass','Biografia / Reflexão','\"Narrativa da Vida de Frederick Douglass, um Escravo Americano\", de Frederick Douglass, é uma autobiografia escrita em 1845. O relato apresenta suas experiências na escravidão e sua determinação em conquistar a liberdade. Sua busca secreta pela alfabetização torna-se um ponto de virada, abrindo sua mente para a possibilidade de fuga e impulsionando sua jornada rumo à libertação e à autodeterminação.',1845,'https://www.gutenberg.org/cache/epub/23/pg23.cover.medium.jpg','https://www.gutenberg.org/cache/epub/23/pg23-images.html'),(99,'Minha Vida — Volume 1','Richard Wagner','Biografia','\"Minha Vida — Volume 1\", de Richard Wagner, é uma autobiografia escrita entre 1865 e 1880, que abrange sua vida desde o nascimento, em 1813, até 1864. Wagner relata sua carreira, amizades e controvérsias, oferecendo um relato de seu desenvolvimento e do mundo musical de sua época.',1911,'https://www.gutenberg.org/cache/epub/5197/pg5197.cover.medium.jpg','https://www.gutenberg.org/cache/epub/5197/pg5197-images.html'),(100,'Ondina','Friedrich de la Motte-Fouqué','Fantasia / Romance','\"Undine\", de Friedrich de la Motte-Fouqué, é um romance de conto de fadas romântico escrito no início do século XIX. A história acompanha Undine, uma ninfa da água, e seus encontros com humanos, especialmente seu relacionamento com Sir Huldbrand de Ringstetten. A narrativa explora amor, sacrifício e a busca pela alma através de elementos sobrenaturais.',1811,'https://www.gutenberg.org/cache/epub/2825/pg2825.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2825/pg2825-images.html'),(101,'Aquilo que Tem Asas','Richard Dehan','Romance / Drama','\"Aquilo Que Tem Asas: Um Romance do Dia\", de Richard Dehan, é um romance escrito no início do século XX. A história gira em torno de Francis, Visconde Norwater, e sua esposa Margot, que enfrentam as provações da vida de recém-casados pouco antes do início da Primeira Guerra Mundial. O romance explora amor, expectativas sociais, maternidade e as sombras iminentes da guerra.',1918,'https://www.gutenberg.org/cache/epub/51428/pg51428.cover.medium.jpg','https://www.gutenberg.org/cache/epub/51428/pg51428-images.html'),(102,'Como Gostais','William Shakespeare','Romance / Comédia','\"Como Gostais\", de William Shakespeare, é uma comédia pastoral escrita em 1599. Quando Rosalinda foge da corte de seu tio, ela se aventura na Floresta de Arden com sua prima Celia. Lá, encontra personagens memoráveis enquanto lida com disfarces, amor e o contraste entre a vida na corte e a vida no campo.',1623,'https://www.gutenberg.org/cache/epub/1523/pg1523.cover.medium.jpg','https://www.gutenberg.org/cache/epub/1523/pg1523-images.html'),(103,'Obras Curtas Completas de George Meredith','George Meredith','Contos / Romance','\"Obras Curtas Completas de George Meredith\", de George Meredith, é uma coletânea de contos e prosa escritos no final do século XIX. A antologia abrange histórias que exploram romance, aventura e crítica social, apresentando personagens e situações variadas, incluindo a história de Farina e suas relações com outros personagens.',1898,'https://www.gutenberg.org/cache/epub/4499/pg4499.cover.medium.jpg','https://www.gutenberg.org/cache/epub/4499/pg4499-images.html'),(104,'O Livro de Versos Doméstico — Volume 2','Burton Egbert Stevenson','Poesia','\"The Home Book of Verse — Volume 2\", de Burton Egbert Stevenson, é uma coletânea de poesia compilada no início do século XX. A antologia apresenta uma variedade de poemas sobre o amor, reunindo diferentes estilos e autores e explorando as diversas formas de experiências românticas e apaixonadas.',1912,'https://www.gutenberg.org/cache/epub/2620/pg2620.cover.medium.jpg','https://www.gutenberg.org/cache/epub/2620/pg2620-images.html'),(105,'O Que Dirão as Pessoas?','Rupert Hughes','Romance','\"O Que Dirão as Pessoas?\", de Rupert Hughes, é um romance escrito no início do século XX. A história acompanha o tenente Harvey Forbes, um jovem soldado recém-chegado das Filipinas, enquanto se adapta ao mundo da cidade de Nova York. A narrativa aborda amor, expectativas sociais e as complexidades das interações humanas em um ambiente urbano em transformação.',1914,'https://www.gutenberg.org/cache/epub/38311/pg38311.cover.medium.jpg','https://www.gutenberg.org/cache/epub/38311/pg38311-images.html'),(106,'O Amor de Henrique VIII por Ana Bolena','Henrique VIII','Romance / História','\"As Cartas de Amor de Henrique VIII para Ana Bolena; Com Anotações de Henrique VIII\" é uma coleção histórica de correspondências escritas no início do século XVI. A compilação destaca o relacionamento romântico e tumultuoso entre Henrique VIII e Ana Bolena, revelando sentimentos profundos, paixão, desespero e as complexidades da vida na corte Tudor.',1976,'https://www.gutenberg.org/cache/epub/32155/pg32155.cover.medium.jpg','https://www.gutenberg.org/cache/epub/32155/pg32155-images.html'),(107,'A Barreira Silenciosa','Louis Tracy','Romance / Aventura','\"A Barreira Silenciosa\", de Louis Tracy, é um romance escrito no início do século XX. A narrativa gira em torno de Charles K. Spencer, um engenheiro de mineração americano que se encanta por Helen Wynton, uma jovem que sonha em viajar para os Alpes Suíços. O desejo de Spencer de proporcionar a Helen uma grande aventura se desenrola em meio a romance e intrigas sociais.',1909,'https://www.gutenberg.org/cache/epub/32155/pg32155.cover.medium.jpg','https://www.gutenberg.org/cache/epub/32155/pg32155-images.html'),(108,'O Herói do Povo','Alexandre Dumas','Aventura / História','\"O Herói do Povo: Um Romance Histórico de Amor, Liberdade e Lealdade\", de Alexandre Dumas, é um romance histórico ambientado durante o período tumultuado da Revolução Francesa. A narrativa acompanha personagens envolvidos nas tensões entre a monarquia e a população, explorando emoções, lealdade, conflitos de classe e a busca do povo pela liberdade.',1928,'https://www.gutenberg.org/cache/epub/42681/pg42681.cover.medium.jpg','https://www.gutenberg.org/cache/epub/42681/pg42681-images.html'),(109,'Uma Mulher: Sendo a Segunda Parte de um Romance de Sussex','Alfred Ollivant','Drama / Romance','\"Uma Mulher: Sendo a Segunda Parte de um Romance de Sussex\", de Alfred Ollivant, é um romance escrito no início do século XX. O livro explora as vidas e os relacionamentos de Ruth Boam e Ernie Caspar, um jovem casal recém-casado, enquanto enfrentam os desafios do amor, da família e das expectativas sociais em Sussex. A alegria do casal contrasta com as complexidades de seus passados, as dinâmicas familiares e os desafios sociais que começam a se entrelaçar na história.',1919,'https://www.gutenberg.org/cache/epub/57641/pg57641.cover.medium.jpg','https://www.gutenberg.org/cache/epub/57641/pg57641-images.html'),(110,'Nas montanhas da loucura','H.P. Lovecraft','Ficção científica','\"Nas Montanhas da Loucura\", de H.P. Lovecraft, é uma novela de ficção científica e horror cósmico escrita em 1931 e publicada em 1936. A história acompanha o Dr. William Dyer enquanto ele narra uma expedição catastrófica à Antártida em 1930, na esperança de impedir que futuros exploradores retornassem. Sua equipe descobre uma antiga civilização alienígena que antecede a humanidade, ruínas preservadas além de montanhas imponentes e criaturas pré-históricas que desafiam a classificação. À medida que desvendam a história aterradora dos habitantes originais da Terra por meio de murais antigos, eles encontram algo muito mais perigoso.',1936,'https://www.gutenberg.org/cache/epub/70652/pg70652.cover.medium.jpg','https://www.gutenberg.org/cache/epub/70652/pg70652-images.html');
